INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2095NPN', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A jacket originally costs $74$ dollars. During a sale, the price is reduced by $35\\%$. What is the sale price of the jacket, in dollars?', NULL, $lyceon_json$[{"key":"A","text":"$48.10$"},{"key":"B","text":"$25.90$"},{"key":"C","text":"$39.00$"},{"key":"D","text":"$55.50$"}]$lyceon_json$::jsonb, 'A', NULL, E'The discount is $0.35 \\times 74 = 25.90$ dollars, so the sale price is $74 - 25.90 = 48.10$ dollars. The value $25.90$ is the discount amount rather than the sale price, reflecting a misread of what the question asks. The value $39.00$ results from a computational error in the percentage calculation. The value $55.50$ comes from applying $25\\%$ off instead of $35\\%$ off.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM21R6TME', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'grid_in', E'A line passes through the points $(0, 7)$ and $(3, 16)$. What is the slope of this line?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '3', ARRAY['3'], E'The slope of a line through two points $(x_1, y_1)$ and $(x_2, y_2)$ is $\\frac{y_2 - y_1}{x_2 - x_1}$. Substituting the given points gives $\\frac{16 - 7}{3 - 0} = \\frac{9}{3} = 3$.', NULL, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM22A5WWT', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'mcq', E'In triangle $ABC$, side $BC$ is extended to point $D$. The exterior angle $ACD$ measures $119°$. If angle $A = (2x + 7)°$ and angle $B = (3x - 8)°$, what is the measure of angle $B$?', NULL, $lyceon_json$[{"key":"A","text":"$24°$"},{"key":"B","text":"$55°$"},{"key":"C","text":"$61°$"},{"key":"D","text":"$64°$"}]$lyceon_json$::jsonb, 'D', NULL, E'By the Exterior Angle Theorem, the exterior angle of a triangle equals the sum of the two non-adjacent interior angles: $119 = (2x + 7) + (3x - 8)$. Simplifying gives $119 = 5x - 1$, so $5x = 120$ and $x = 24$. Then angle $B = 3(24) - 8 = 64°$. The value $24°$ results from reporting the value of $x$ rather than substituting back to find the angle measure. The value $55°$ is the measure of angle $A$, computed as $2(24) + 7 = 55°$, but the question asks for angle $B$. The value $61°$ results from computing the supplement $180° - 119° = 61°$, which gives angle $C$ rather than angle $B$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25DQLYV', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'grid_in', E'A circle has center $(2, -7)$ and passes through the point $(10, -1)$. What is the radius of the circle?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '10', ARRAY['10'], E'The radius equals the distance from the center to the given point on the circle. Using the distance formula: $r = \\sqrt{(10 - 2)^2 + (-1 - (-7))^2} = \\sqrt{8^2 + 6^2} = \\sqrt{64 + 36} = \\sqrt{100} = 10$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25WPMSA', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'grid_in', E'If $x > 0$ and $2x^2 + 7x - 15 = 0$, what is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '3/2', ARRAY['3/2', '1.5'], E'Using the quadratic formula with $a = 2$, $b = 7$, and $c = -15$: $$x = \\frac{-7 \\pm \\sqrt{49 + 120}}{4} = \\frac{-7 \\pm \\sqrt{169}}{4} = \\frac{-7 \\pm 13}{4}$$ This gives $x = \\frac{6}{4} = \\frac{3}{2}$ or $x = \\frac{-20}{4} = -5$. Since $x > 0$, the answer is $\\frac{3}{2}$. Alternatively, the equation factors as $(2x - 3)(x + 5) = 0$, giving $x = \\frac{3}{2}$ or $x = -5$, and the positive solution is $\\frac{3}{2}$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25XSPL6', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'grid_in', E'The expression $\\frac{8x^3 + 27}{4x^2 - 9}$ can be written in the form $\\frac{ax^2 + bx + c}{dx + e}$ for constants $a$, $b$, $c$, $d$, and $e$, provided $x \\neq \\pm\\frac{3}{2}$. What is the value of $a + b + c + d + e$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '6', ARRAY['6'], E'The numerator is a sum of cubes: $8x^3 + 27 = (2x)^3 + 3^3 = (2x + 3)(4x^2 - 6x + 9)$. The denominator is a difference of squares: $4x^2 - 9 = (2x - 3)(2x + 3)$. Cancelling the common factor $(2x + 3)$ gives $\\frac{4x^2 - 6x + 9}{2x - 3}$. Thus $a = 4$, $b = -6$, $c = 9$, $d = 2$, and $e = -3$, and the sum is $4 + (-6) + 9 + 2 + (-3) = 6$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27I4EWB', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'grid_in', E'Line $p$ has the equation $5x - 2y = 14$. Line $q$ is perpendicular to line $p$ and passes through the point $(7, -3)$. What is the $y$-intercept of line $q$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-1/5', ARRAY['-1/5', '-0.2', '-.2'], E'Rewriting line $p$ in slope-intercept form: $-2y = -5x + 14$, so $y = \\frac{5}{2}x - 7$. The slope of line $p$ is $\\frac{5}{2}$. A line perpendicular to line $p$ has slope $-\\frac{2}{5}$ (the negative reciprocal). Using point-slope form with the point $(7, -3)$: $y - (-3) = -\\frac{2}{5}(x - 7)$, which gives $y + 3 = -\\frac{2}{5}x + \\frac{14}{5}$. Solving for $y$: $y = -\\frac{2}{5}x + \\frac{14}{5} - \\frac{15}{5} = -\\frac{2}{5}x - \\frac{1}{5}$. The $y$-intercept is $-\\frac{1}{5}$.', NULL, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM282EM9G', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which expression is equivalent to $3(2x^2 - 7x + 4) - (x^2 + 5x - 9)$?', NULL, $lyceon_json$[{"key":"A","text":"$5x^2 - 26x + 21$"},{"key":"B","text":"$5x^2 - 26x + 3$"},{"key":"C","text":"$5x^2 - 16x + 21$"},{"key":"D","text":"$7x^2 - 26x + 21$"}]$lyceon_json$::jsonb, 'A', NULL, E'Distributing the $3$ gives $6x^2 - 21x + 12$. Distributing the subtraction across the second group gives $-x^2 - 5x + 9$. Combining like terms: $6x^2 - x^2 = 5x^2$, $-21x - 5x = -26x$, and $12 + 9 = 21$, yielding $5x^2 - 26x + 21$. The result $5x^2 - 26x + 3$ comes from failing to distribute the negative sign to $-9$, treating $12 - 9 = 3$ instead of $12 + 9 = 21$. The result $5x^2 - 16x + 21$ comes from failing to distribute the negative sign to $5x$, computing $-21x + 5x = -16x$ instead of $-21x - 5x = -26x$. The result $7x^2 - 26x + 21$ comes from adding instead of subtracting the $x^2$ terms, computing $6x^2 + x^2 = 7x^2$ instead of $6x^2 - x^2 = 5x^2$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29NT7GE', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The function $p$ is defined by $p(x) = a \\cdot b^x$, where $a$ and $b$ are positive constants. If $p(2) = 75$ and $p(5) = 9375$, what is the value of $p(0)$?', NULL, $lyceon_json$[{"key":"A","text":"$1$"},{"key":"B","text":"$3$"},{"key":"C","text":"$5$"},{"key":"D","text":"$15$"}]$lyceon_json$::jsonb, 'B', NULL, E'Since $p(x) = a \\cdot b^x$, we have $p(2) = ab^2 = 75$ and $p(5) = ab^5 = 9375$. Dividing these equations gives $b^3 = \\frac{9375}{75} = 125$, so $b = 5$. Substituting back: $a \\cdot 25 = 75$, giving $a = 3$. Therefore $p(0) = a \\cdot b^0 = a \\cdot 1 = 3$. The value $1$ results from computing $b^0 = 1$ but forgetting to multiply by $a$, reflecting a gap in understanding that $p(0) = a$, not $b^0$. The value $5$ results from finding $b = 5$ and stopping there, without completing the calculation to find $a$. The value $15$ results from an arithmetic error such as computing $a = 75 / 5 = 15$ instead of correctly dividing $75 / 25 = 3$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2APIQFN', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'A line of best fit for a scatterplot is given by $y = 2.3x + 4.1$. According to this model, what is the predicted value of $y$ when $x = 7$?', NULL, $lyceon_json$[{"key":"A","text":"$20.2$"},{"key":"B","text":"$16.1$"},{"key":"C","text":"$18.4$"},{"key":"D","text":"$22.5$"}]$lyceon_json$::jsonb, 'A', NULL, E'Substituting $x = 7$: $y = 2.3(7) + 4.1 = 16.1 + 4.1 = 20.2$. The value $16.1$ results from computing only $2.3 \\times 7$ and omitting the $y$-intercept of $4.1$. The value $18.4$ comes from a multiplication error such as $2.3 \\times 7 = 14.3$. The value $22.5$ arises from an arithmetic slip when adding $16.1 + 4.1$ or from using an incorrect coefficient.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AY1LI9', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'In a class of $31$ students, $13$ play soccer, $11$ play basketball, and $5$ play both soccer and basketball. If a student is chosen at random from those who play soccer, what is the probability that the student also plays basketball?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{5}{31}$"},{"key":"B","text":"$\\frac{5}{13}$"},{"key":"C","text":"$\\frac{5}{11}$"},{"key":"D","text":"$\\frac{8}{13}$"}]$lyceon_json$::jsonb, 'B', NULL, E'This is a conditional probability question. Given that the student plays soccer, the sample space is the $13$ soccer players. Of those, $5$ also play basketball, so the probability is $\\frac{5}{13}$. The value $\\frac{5}{31}$ incorrectly uses the entire class of $31$ as the denominator instead of conditioning on soccer players. The value $\\frac{5}{11}$ incorrectly conditions on basketball players ($11$) rather than soccer players. The value $\\frac{8}{13}$ uses $13 - 5 = 8$ in the numerator, representing soccer-only players instead of those who play both sports.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BL1GPY', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'A bakery charges $4$ dollars per loaf of sourdough bread and $6$ dollars per loaf of rye bread. A customer wants to buy at least one loaf of each type and spend no more than $38$ dollars total. If $s$ represents the number of sourdough loaves and $r$ represents the number of rye loaves, which inequality represents this situation?', NULL, $lyceon_json$[{"key":"A","text":"$4s + 6r \\leq 38$"},{"key":"B","text":"$4s + 6r \\geq 38$"},{"key":"C","text":"$6s + 4r \\leq 38$"},{"key":"D","text":"$4s + 6r < 38$"}]$lyceon_json$::jsonb, 'A', NULL, E'Sourdough costs $4$ dollars per loaf and rye costs $6$ dollars per loaf, so the total cost is $4s + 6r$. The phrase ''no more than $38$ dollars'' means the total must be less than or equal to $38$, giving $4s + 6r \\leq 38$. The option $4s + 6r \\geq 38$ reverses the inequality direction, confusing a budget ceiling with a spending minimum. The option $6s + 4r \\leq 38$ swaps the coefficients, assigning the rye price to sourdough and vice versa. The option $4s + 6r < 38$ uses a strict inequality, but ''no more than'' includes spending exactly $38$ dollars.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BLRAPR', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'In triangle $RST$, angle $R$ measures $47°$ and angle $S$ measures $68°$. What is the measure, in degrees, of angle $T$?', NULL, $lyceon_json$[{"key":"A","text":"$55°$"},{"key":"B","text":"$65°$"},{"key":"C","text":"$75°$"},{"key":"D","text":"$115°$"}]$lyceon_json$::jsonb, 'B', NULL, E'The sum of angles in a triangle is $180°$. Therefore angle $T = 180° - 47° - 68° = 65°$. The value $55°$ results from an arithmetic error when subtracting from $180°$. The value $75°$ comes from misreading one of the given angle measures during computation. The value $115°$ is simply $47° + 68°$, reflecting an incomplete calculation that stops at the sum of the two given angles without subtracting from $180°$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2BNLRS3', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'grid_in', E'A cylinder has a radius of $5$ cm and a height of $13$ cm. The volume of the cylinder can be written as $k\\pi$ cubic centimeters. What is the value of $k$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '325', ARRAY['325'], E'The volume of a cylinder is $V = \\pi r^2 h$. Substituting the given values: $V = \\pi (5)^2 (13) = \\pi (25)(13) = 325\\pi$. Therefore $k = 325$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2C11U0E', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'mcq', E'What are the solutions to the equation $x^2 - 11x + 24 = 0$?', NULL, $lyceon_json$[{"key":"A","text":"$x = 4$ and $x = 6$"},{"key":"B","text":"$x = -3$ and $x = -8$"},{"key":"C","text":"$x = 3$ and $x = 8$"},{"key":"D","text":"$x = 2$ and $x = 12$"}]$lyceon_json$::jsonb, 'C', NULL, E'The equation factors as $(x - 3)(x - 8) = 0$, since $(-3)(-8) = 24$ and $(-3) + (-8) = -11$. Setting each factor equal to zero gives $x = 3$ and $x = 8$. The pair $x = 4$ and $x = 6$ has the correct product ($4 \\times 6 = 24$) but the wrong sum ($4 + 6 = 10 \\neq 11$), reflecting an arithmetic slip in finding the factor pair. The pair $x = -3$ and $x = -8$ results from a sign error — using the roots of $(x + 3)(x + 8) = 0$ instead of $(x - 3)(x - 8) = 0$. The pair $x = 2$ and $x = 12$ also has the correct product ($2 \\times 12 = 24$) but the wrong sum ($2 + 12 = 14 \\neq 11$).', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CUXBML', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'mcq', E'A store marks up the wholesale cost of an item by $60\\%$ to set the retail price. During a clearance event, the store offers a $25\\%$ discount on the retail price and then applies an additional $10\\%$ loyalty discount on the already-reduced price. If the wholesale cost of the item is $85$ dollars, what is the final price a loyalty member pays, in dollars?', NULL, $lyceon_json$[{"key":"A","text":"$91.80$"},{"key":"B","text":"$102.00$"},{"key":"C","text":"$88.40$"},{"key":"D","text":"$95.20$"}]$lyceon_json$::jsonb, 'A', NULL, E'The retail price is $85 \\times 1.60 = 136$ dollars. After the $25\\%$ discount: $136 \\times 0.75 = 102$ dollars. After the additional $10\\%$ loyalty discount: $102 \\times 0.90 = 91.80$ dollars. The value $102$ results from applying only the first discount and stopping before the loyalty discount. The value $88.40$ comes from combining the two discounts as a single $35\\%$ off the retail price ($136 \\times 0.65 = 88.40$), which incorrectly treats sequential discounts as additive. The value $95.20$ results from an arithmetic error when computing the loyalty discount step.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EVX4OV', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'A plumber charges a flat fee of 47 dollars for a service call plus 31 dollars for each hour of labor. Which function $f$ gives the total charge, in dollars, for a service call that requires $h$ hours of labor?', NULL, $lyceon_json$[{"key":"A","text":"$f(h) = 31h - 47$"},{"key":"B","text":"$f(h) = 47h + 31$"},{"key":"C","text":"$f(h) = 78h$"},{"key":"D","text":"$f(h) = 31h + 47$"}]$lyceon_json$::jsonb, 'D', NULL, E'The total charge consists of a flat fee of 47 dollars (constant term) plus 31 dollars per hour (the rate multiplied by $h$), giving $f(h) = 31h + 47$. The expression $31h - 47$ incorrectly subtracts the flat fee instead of adding it. The expression $47h + 31$ reverses the roles of the hourly rate and flat fee, treating 47 as the per-hour charge. The expression $78h$ incorrectly adds the two values into a single hourly rate, eliminating the flat fee entirely.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2F04COE', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'mcq', E'The function $g$ is defined by $g(x) = ax + b$, where $a$ and $b$ are constants. If $g(3) = 19$ and $g(-2) = -11$, what is the value of $g(7)$?', NULL, $lyceon_json$[{"key":"A","text":"$1$"},{"key":"B","text":"$6$"},{"key":"C","text":"$41$"},{"key":"D","text":"$43$"}]$lyceon_json$::jsonb, 'D', NULL, E'From $g(3) = 19$: $3a + b = 19$. From $g(-2) = -11$: $-2a + b = -11$. Subtracting the second equation from the first gives $5a = 30$, so $a = 6$. Substituting back: $3(6) + b = 19$, which gives $b = 1$. Therefore $g(x) = 6x + 1$, and $g(7) = 6(7) + 1 = 43$. The value $1$ is the constant $b$, which would result from finding the function but reporting the wrong quantity. The value $6$ is the slope $a$, which would result from stopping after finding the rate of change without computing $g(7)$. The value $41$ results from an arithmetic error in computing $6 \\times 7$ as $40$ instead of $42$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2F7EF4C', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'grid_in', E'The system of equations $y = x^2 - 6x + k$ and $y = 3x - 11$ has exactly one solution. What is the value of $k$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '37/4', ARRAY['37/4', '9.25'], E'Setting the two expressions for $y$ equal gives $x^2 - 6x + k = 3x - 11$, which simplifies to $x^2 - 9x + (k + 11) = 0$. For the system to have exactly one solution, this quadratic must have exactly one real root, so its discriminant must equal zero. The discriminant is $(-9)^2 - 4(1)(k + 11) = 81 - 4k - 44 = 37 - 4k$. Setting this equal to zero: $37 - 4k = 0$, so $k = \\frac{37}{4}$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FB7WMT', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which expression is equivalent to $\\frac{x^2 + 3x - 28}{x^2 - 16}$ for all values of $x$ where the expression is defined?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{x - 7}{x - 4}$"},{"key":"B","text":"$\\frac{x + 7}{x + 4}$"},{"key":"C","text":"$\\frac{x + 7}{x - 4}$"},{"key":"D","text":"$\\frac{x - 7}{x + 4}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The numerator factors as $(x + 7)(x - 4)$ because $7 \\times (-4) = -28$ and $7 + (-4) = 3$. The denominator is a difference of squares: $x^2 - 16 = (x - 4)(x + 4)$. Cancelling the common factor $(x - 4)$ gives $\\frac{x + 7}{x + 4}$. The result $\\frac{x - 7}{x - 4}$ arises from using incorrect signs in both factors of the numerator. The result $\\frac{x + 7}{x - 4}$ arises from incorrectly factoring $x^2 - 16$ as $(x - 4)^2$ rather than $(x - 4)(x + 4)$, reflecting a gap in the difference-of-squares concept. The result $\\frac{x - 7}{x + 4}$ arises from incorrectly factoring the numerator as $(x - 7)(x + 4)$, which gives $x^2 - 3x - 28$ instead of $x^2 + 3x - 28$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FJJMEM', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'mcq', E'What is the $y$-intercept of the line $11x - 5y = 55$?', NULL, $lyceon_json$[{"key":"A","text":"$-11$"},{"key":"B","text":"$-5$"},{"key":"C","text":"$5$"},{"key":"D","text":"$11$"}]$lyceon_json$::jsonb, 'A', NULL, E'Setting $x = 0$ in $11x - 5y = 55$ gives $-5y = 55$, so $y = -11$. The value $-5$ results from dividing $55$ by $11$ instead of $5$, confusing the coefficients. The value $5$ results from dividing $55$ by $11$ and also dropping the negative sign. The value $11$ results from correctly dividing $55$ by $5$ but dropping the negative sign.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2G1FN78', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A rectangular garden has a length of $29$ meters and a width of $13$ meters. What is the area, in square meters, of the garden?', NULL, $lyceon_json$[{"key":"A","text":"$42$"},{"key":"B","text":"$84$"},{"key":"C","text":"$319$"},{"key":"D","text":"$377$"}]$lyceon_json$::jsonb, 'D', NULL, E'The area of a rectangle is length times width: $29 \\times 13 = 377$ square meters. The value $42$ results from adding the two sides ($29 + 13 = 42$), confusing perimeter with area. The value $84$ results from computing the perimeter $2(29 + 13) = 84$ instead of the area. The value $319$ results from an arithmetic error such as computing $29 \\times 11 = 319$ instead of $29 \\times 13$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 35, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2G5LETJ', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has the equation $(x - 5)^2 + (y + 3)^2 = 49$. What is the radius of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$-7$"},{"key":"B","text":"$7$"},{"key":"C","text":"$14$"},{"key":"D","text":"$49$"}]$lyceon_json$::jsonb, 'B', NULL, E'The standard form of a circle equation is $(x - h)^2 + (y - k)^2 = r^2$. Comparing with the given equation, $r^2 = 49$, so $r = 7$. The value $-7$ incorrectly applies a negative sign, but the radius is always a positive quantity. The value $14$ is the diameter ($2 \\times 7$), not the radius. The value $49$ confuses $r^2$ with $r$, reporting the squared radius instead of taking the square root.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GCLVXO', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'grid_in', E'The function $f$ is defined by $f(x) = 11x - 23$. What is the value of $f(4)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '21', ARRAY['21'], E'Substituting $x = 4$ into the function gives $f(4) = 11(4) - 23 = 44 - 23 = 21$.', NULL, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HVOE68', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'mcq', E'The population of a town was $8{,}700$ in 2018. By 2023, the population had increased to $11{,}310$. What is the percent increase in the population from 2018 to 2023?', NULL, $lyceon_json$[{"key":"A","text":"$23\\%$"},{"key":"B","text":"$30\\%$"},{"key":"C","text":"$26\\%$"},{"key":"D","text":"$33\\%$"}]$lyceon_json$::jsonb, 'B', NULL, E'The increase is $11{,}310 - 8{,}700 = 2{,}610$. The percent increase is $\\frac{2{,}610}{8{,}700} \\times 100 = 30\\%$. The value $23\\%$ results from dividing the increase by the final population ($\\frac{2610}{11310} \\approx 23\\%$) instead of the original population. The value $26\\%$ comes from a computational error in the division. The value $33\\%$ arises from using an incorrect difference in the calculation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ICDSH5', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A researcher surveys a random sample of $400$ households in a county and finds that $37\\%$ have installed solar panels. The margin of error is $\\pm 3$ percentage points at a $95\\%$ confidence level. A second researcher surveys a random sample of $1{,}600$ households from the same county using the same method. If the second survey also finds that $37\\%$ have installed solar panels, which of the following best describes the margin of error for the second survey?', NULL, $lyceon_json$[{"key":"A","text":"The margin of error is approximately $\\pm 1.5$ percentage points."},{"key":"B","text":"The margin of error is approximately $\\pm 3$ percentage points."},{"key":"C","text":"The margin of error is approximately $\\pm 0.75$ percentage points."},{"key":"D","text":"The margin of error is approximately $\\pm 6$ percentage points."}]$lyceon_json$::jsonb, 'A', NULL, E'The margin of error is inversely proportional to the square root of the sample size. Quadrupling the sample size from $400$ to $1{,}600$ halves the margin of error: $\\frac{3}{\\sqrt{4}} = \\frac{3}{2} = 1.5$ percentage points. The value of $\\pm 3$ percentage points assumes the margin of error stays the same regardless of sample size, reflecting a misunderstanding of the relationship. The value $\\pm 0.75$ results from dividing by $4$ instead of $\\sqrt{4}$, confusing the linear factor with the square-root relationship. The value $\\pm 6$ results from multiplying the margin of error by $2$ instead of dividing, reversing the relationship between sample size and margin of error.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2J88LIQ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'grid_in', E'A solution is made by mixing compound $X$ and compound $Y$ in a ratio of $5:4$ by mass. A second solution mixes compound $X$ and compound $Y$ in a ratio of $3:7$ by mass. If $270$ grams of the first solution are combined with $200$ grams of the second solution, what is the ratio of compound $X$ to compound $Y$ in the combined mixture? Express your answer as a fraction.', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '21/26', ARRAY['21/26', '0.807', '.807', '0.808', '.808'], E'In the first solution, compound $X$ is $\\frac{5}{9} \\times 270 = 150$ grams and compound $Y$ is $\\frac{4}{9} \\times 270 = 120$ grams. In the second solution, compound $X$ is $\\frac{3}{10} \\times 200 = 60$ grams and compound $Y$ is $\\frac{7}{10} \\times 200 = 140$ grams. The total compound $X$ is $150 + 60 = 210$ grams and total compound $Y$ is $120 + 140 = 260$ grams. The ratio of $X$ to $Y$ is $\\frac{210}{260} = \\frac{21}{26}$. Common errors include using the wrong total for one solution (e.g., dividing by $9$ for both solutions) or forgetting to combine the components from both solutions.', NULL, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JA2V8L', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A cyclist travels $13$ kilometers in $47$ minutes. A runner covers $5$ kilometers in $29$ minutes. How many more kilometers per hour does the cyclist travel than the runner, to the nearest tenth?', NULL, $lyceon_json$[{"key":"A","text":"$6.2$"},{"key":"B","text":"$6.3$"},{"key":"C","text":"$5.6$"},{"key":"D","text":"$6.6$"}]$lyceon_json$::jsonb, 'B', NULL, E'The cyclist''s rate is $\\frac{13}{47} \\times 60 \\approx 16.596$ km/hr. The runner''s rate is $\\frac{5}{29} \\times 60 \\approx 10.345$ km/hr. The difference is approximately $16.596 - 10.345 = 6.251$, which rounds to $6.3$ km/hr. The value $6.2$ results from truncating the difference at the tenths place instead of rounding (the hundredths digit is $5$, so the tenths digit rounds up). The value $5.6$ comes from computing per-minute rate differences without properly converting to per-hour units. The value $6.6$ arises from a unit conversion error when computing the runner''s speed.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"unit_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JT13BZ', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'grid_in', E'What is the value of $x$ that satisfies the equation $$\\frac{3(x + 4)}{7} - \\frac{2x - 1}{3} = 2\\text{ ?}$$', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '1/5', ARRAY['1/5', '0.2', '.2'], E'Multiplying every term by the least common denominator, 21, eliminates the fractions: $21 \\cdot \\frac{3(x+4)}{7} - 21 \\cdot \\frac{2x-1}{3} = 21 \\cdot 2$. This simplifies to $9(x + 4) - 7(2x - 1) = 42$. Expanding gives $9x + 36 - 14x + 7 = 42$, which combines to $-5x + 43 = 42$. Subtracting 43 from both sides gives $-5x = -1$, so $x = \\frac{1}{5}$.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JW0FT1', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $f$ is defined by $f(x) = x^3$. The function $g$ is obtained by translating the graph of $f$ to the right by $5$ units and down by $2$ units. Which of the following defines $g(x)$?', NULL, $lyceon_json$[{"key":"A","text":"$g(x) = (x + 5)^3 - 2$"},{"key":"B","text":"$g(x) = (x - 5)^3 + 2$"},{"key":"C","text":"$g(x) = (x - 5)^3 - 2$"},{"key":"D","text":"$g(x) = (x - 2)^3 - 5$"}]$lyceon_json$::jsonb, 'C', NULL, E'A horizontal translation to the right by $5$ units replaces $x$ with $(x - 5)$, and a vertical translation down by $2$ units subtracts $2$ from the output. Thus $g(x) = (x - 5)^3 - 2$. The expression $(x + 5)^3 - 2$ uses the wrong sign for the horizontal shift — adding $5$ instead of subtracting shifts the graph left, not right. The expression $(x - 5)^3 + 2$ uses the correct horizontal shift but applies the wrong sign for the vertical shift, moving the graph up instead of down. The expression $(x - 2)^3 - 5$ swaps the horizontal and vertical shift values, applying $2$ as the horizontal shift and $5$ as the vertical shift.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 70, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2KGMQ3F', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'A university researcher wants to test whether listening to classical music while studying improves exam performance. She recruits $120$ volunteers and randomly assigns $60$ to study with classical music and $60$ to study in silence. The classical music group scores an average of $4.7$ points higher on the exam. However, a reviewer notes that $42$ of the $60$ students in the classical music group were music majors, compared to only $11$ of the $60$ in the silence group. Which of the following best explains why the study''s conclusion may not be valid?', NULL, $lyceon_json$[{"key":"A","text":"The sample size of $120$ is too small to detect a $4.7$-point difference."},{"key":"B","text":"The unequal distribution of music majors between groups is a confounding variable that undermines the causal claim."},{"key":"C","text":"The study should have used an observational design instead of an experiment."},{"key":"D","text":"The $4.7$-point difference is not large enough to be practically meaningful."}]$lyceon_json$::jsonb, 'B', NULL, E'Although the study uses random assignment, the resulting groups are highly imbalanced: $42$ out of $60$ music-group participants are music majors versus $11$ out of $60$ in the silence group. Music majors may inherently perform differently on exams regardless of study conditions, so this imbalance acts as a confounding variable that undermines the causal conclusion. The claim that $120$ participants is too small ignores that sample size adequacy depends on effect size and variability, not an arbitrary threshold, and the question focuses on group composition, not sample size. Suggesting an observational design misunderstands that experiments with random assignment are generally stronger for causal inference -- the issue here is the flawed execution of randomization, not the experimental design itself. The claim that $4.7$ points is not practically meaningful addresses a different concern (practical significance) rather than the internal validity problem created by the unbalanced groups.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2L3A9DN', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'mcq', E'The equation of a circle is $x^2 + y^2 - 6x + 10y + 9 = 0$. A line is tangent to this circle at the point $(0, -1)$. What is the slope of the tangent line?', NULL, $lyceon_json$[{"key":"A","text":"$-\\frac{4}{3}$"},{"key":"B","text":"$-\\frac{3}{4}$"},{"key":"C","text":"$\\frac{3}{4}$"},{"key":"D","text":"$\\frac{4}{3}$"}]$lyceon_json$::jsonb, 'C', NULL, E'First, complete the square: $x^2 - 6x + 9 + y^2 + 10y + 25 = -9 + 9 + 25$, giving $(x - 3)^2 + (y + 5)^2 = 25$. The center is $(3, -5)$ and the radius is $5$. The slope of the radius from $(3, -5)$ to the tangent point $(0, -1)$ is $\\frac{-1 - (-5)}{0 - 3} = \\frac{4}{-3} = -\\frac{4}{3}$. Since the tangent line is perpendicular to the radius, its slope is the negative reciprocal: $\\frac{3}{4}$. The value $-\\frac{4}{3}$ is the slope of the radius itself, not the tangent. The value $-\\frac{3}{4}$ results from negating the correct tangent slope rather than negating the reciprocal. The value $\\frac{4}{3}$ results from taking the reciprocal of the radius slope without applying the sign change.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2LU9DZG', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A bag contains $8$ red marbles, $6$ blue marbles, and $2$ green marbles. If one marble is selected at random, what is the probability that it is blue?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{1}{6}$"},{"key":"B","text":"$\\frac{3}{8}$"},{"key":"C","text":"$\\frac{6}{14}$"},{"key":"D","text":"$\\frac{6}{8}$"}]$lyceon_json$::jsonb, 'B', NULL, E'The total number of marbles is $8 + 6 + 2 = 16$. The probability of selecting a blue marble is $\\frac{6}{16}$, which simplifies to $\\frac{3}{8}$. The value $\\frac{1}{6}$ results from confusing the count of blue marbles with the total. The value $\\frac{6}{14}$ results from miscounting the total as $14$ by omitting the green marbles. The value $\\frac{6}{8}$ results from using only the red marble count as the denominator instead of the total.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2NSKYG5', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'Which of the following values of $x$ satisfies the inequality $5x - 11 > 24$?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$5$"},{"key":"C","text":"$7$"},{"key":"D","text":"$8$"}]$lyceon_json$::jsonb, 'D', NULL, E'Adding $11$ to both sides gives $5x > 35$, so $x > 7$. The value $8$ is greater than $7$, so it satisfies the strict inequality. The value $3$ does not satisfy the inequality because $5(3) - 11 = 4$, which is not greater than $24$. The value $5$ gives $5(5) - 11 = 14$, which is not greater than $24$. The value $7$ gives $5(7) - 11 = 24$, which equals $24$ but is not strictly greater than it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
