INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2P9AVY9', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'mcq', E'A survey of $200$ employees at a company recorded their department and whether they commute by train. Of the $74$ employees in the engineering department, $41$ commute by train. Of the $126$ employees in all other departments, $53$ commute by train. If an employee who commutes by train is selected at random, what is the probability that the employee is NOT in the engineering department?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{53}{94}$"},{"key":"B","text":"$\\frac{53}{126}$"},{"key":"C","text":"$\\frac{53}{200}$"},{"key":"D","text":"$\\frac{73}{126}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The total number of employees who commute by train is $41 + 53 = 94$. Given the employee commutes by train, the probability of NOT being in engineering is the number of train commuters outside engineering divided by the total train commuters: $\\frac{53}{94}$. The value $\\frac{53}{126}$ incorrectly uses the total non-engineering employees ($126$) as the denominator rather than conditioning on train commuters. The value $\\frac{53}{200}$ uses the entire company ($200$) as the denominator, ignoring the conditional. The value $\\frac{73}{126}$ uses $126 - 53 = 73$ as the numerator, which represents non-engineering employees who do NOT commute by train, divided by all non-engineering employees.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QJRJIK', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'grid_in', E'A data set contains the values $14, 19, 23, 23, 27, 31, 38$. What is the median of this data set?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '23', ARRAY['23'], E'The data set has $7$ values already listed in increasing order. The median is the middle value, which is the 4th value: $23$. A common error is computing the mean instead of the median, or selecting the 3rd or 5th value by miscounting the middle position.', NULL, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2QKVZS3', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'What is the solution to the equation $3(2x - 5) + 11 = 5x - 3$?', NULL, $lyceon_json$[{"key":"A","text":"$-9$"},{"key":"B","text":"$-6$"},{"key":"C","text":"$-1$"},{"key":"D","text":"$1$"}]$lyceon_json$::jsonb, 'D', NULL, E'Distributing on the left side gives $6x - 15 + 11 = 5x - 3$, which simplifies to $6x - 4 = 5x - 3$. Subtracting $5x$ from both sides gives $x - 4 = -3$, and adding 4 to both sides yields $x = 1$. The value $-9$ results from incorrectly distributing 3 only to the first term ($6x - 5$ instead of $6x - 15$), leading to $6x + 6 = 5x - 3$. The value $-6$ results from a multiplication error in the distribution ($3 \\times 5 = 8$ instead of 15). The value $-1$ results from a sign error when moving the constant term across the equation.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2R7X1S5', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'The system of equations $9x - 4y = 23$ and $3x + ky = 11$ has no solution. What is the value of $k$?', NULL, $lyceon_json$[{"key":"A","text":"$-\\frac{4}{3}$"},{"key":"B","text":"$\\frac{4}{3}$"},{"key":"C","text":"$-12$"},{"key":"D","text":"$12$"}]$lyceon_json$::jsonb, 'A', NULL, E'For the system to have no solution, the lines must be parallel, meaning they have the same slope but different $y$-intercepts. Multiplying the second equation by $3$ gives $9x + 3ky = 33$. For the $x$ and $y$ coefficients to be proportional to those in $9x - 4y = 23$, we need $3k = -4$, so $k = -\\frac{4}{3}$. Checking that the system is indeed inconsistent: the first equation has constant $23$ while the scaled second equation has constant $33$, confirming no solution. The value $\\frac{4}{3}$ results from dropping the negative sign when solving $3k = -4$. The value $-12$ comes from incorrectly multiplying $-4$ by $3$ instead of dividing. The value $12$ results from both ignoring the negative sign and multiplying instead of dividing.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2R9UYNR', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $g$ is defined by $g(x) = (x - 4)^2 + 7$. What is the minimum value of $g(x)$?', NULL, $lyceon_json$[{"key":"A","text":"$-4$"},{"key":"B","text":"$4$"},{"key":"C","text":"$7$"},{"key":"D","text":"$11$"}]$lyceon_json$::jsonb, 'C', NULL, E'The function $g(x) = (x - 4)^2 + 7$ is in vertex form $a(x - h)^2 + k$ with $h = 4$ and $k = 7$. Since $(x - 4)^2 \\geq 0$ for all real $x$, the smallest value of $g(x)$ is $0 + 7 = 7$, occurring at $x = 4$. The value $-4$ comes from misreading the question and extracting the sign-reversed horizontal shift. The value $4$ comes from giving the $x$-coordinate of the vertex rather than the minimum output value, reflecting a gap in understanding vertex form. The value $11$ comes from incorrectly adding $4 + 7$ as though both parameters contribute to the minimum.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 40, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RKOH0C', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'mcq', E'A teacher records the following quiz scores for $9$ students: $62, 71, 74, 78, 78, 83, 85, 91, 96$. If the score of $96$ is replaced by $78$, which of the following statements correctly describes the change in the mean and the median?', NULL, $lyceon_json$[{"key":"A","text":"Both the mean and the median decrease."},{"key":"B","text":"The mean decreases, but the median stays the same."},{"key":"C","text":"The mean stays the same, but the median decreases."},{"key":"D","text":"Both the mean and the median stay the same."}]$lyceon_json$::jsonb, 'B', NULL, E'The original sum is $62 + 71 + 74 + 78 + 78 + 83 + 85 + 91 + 96 = 718$, giving a mean of $\\frac{718}{9} \\approx 79.8$. Replacing $96$ with $78$ reduces the sum to $700$, yielding a new mean of $\\frac{700}{9} \\approx 77.8$, so the mean decreases. The original median (5th value of $9$) is $78$. After replacement, the sorted data is $62, 71, 74, 78, 78, 78, 83, 85, 91$, and the 5th value is still $78$, so the median is unchanged. The claim that both decrease incorrectly assumes the median shifts. The claim that the mean stays the same ignores the reduced sum. The claim that both stay the same overlooks the change in the total.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2T0G54S', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A random sample of $250$ voters in a city found that $58\\%$ support a proposed library expansion. The margin of error for the survey is $4$ percentage points. Which of the following is the best interpretation of this result?', NULL, $lyceon_json$[{"key":"A","text":"Between $54\\%$ and $62\\%$ of all voters in the city are likely to support the expansion."},{"key":"B","text":"Exactly $58\\%$ of all voters in the city support the expansion."},{"key":"C","text":"Between $54\\%$ and $62\\%$ of the $250$ sampled voters support the expansion."},{"key":"D","text":"The survey is $58\\%$ accurate."}]$lyceon_json$::jsonb, 'A', NULL, E'A margin of error of $4$ percentage points means the plausible range for the true population proportion is $58\\% \\pm 4\\%$, or between $54\\%$ and $62\\%$, for all voters in the city. The claim that exactly $58\\%$ of all voters support the expansion ignores the uncertainty captured by the margin of error. The claim that the range applies to the $250$ sampled voters confuses the sample statistic with the population inference -- the sample result is already known to be $58\\%$. The statement that the survey is $58\\%$ accurate misinterprets the percentage as a measure of survey accuracy rather than the sample proportion.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TOCNS3', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'mcq', E'A right circular cylinder with radius $4$ cm is inscribed in a sphere of radius $7$ cm, with both circular bases of the cylinder touching the sphere. What is the height of the cylinder?', NULL, $lyceon_json$[{"key":"A","text":"$\\sqrt{33}$"},{"key":"B","text":"$6$"},{"key":"C","text":"$2\\sqrt{33}$"},{"key":"D","text":"$2\\sqrt{65}$"}]$lyceon_json$::jsonb, 'C', NULL, E'For a cylinder inscribed in a sphere, a right triangle is formed by the cylinder radius $r$, half the cylinder height $\\frac{h}{2}$, and the sphere radius $R$ as the hypotenuse: $r^2 + \\left(\\frac{h}{2}\\right)^2 = R^2$. Substituting $r = 4$ and $R = 7$: $16 + \\frac{h^2}{4} = 49$, so $\\frac{h^2}{4} = 33$, giving $h^2 = 132$ and $h = 2\\sqrt{33}$. The value $\\sqrt{33}$ results from omitting the factor of $2$, using $r^2 + h^2 = R^2$ instead of $r^2 + (h/2)^2 = R^2$, which yields $h = \\sqrt{33}$. The value $6$ comes from the incorrect formula $h = 2(R - r) = 2(7 - 4) = 6$, which conflates linear subtraction with the Pythagorean relationship. The value $2\\sqrt{65}$ results from adding $R^2 + r^2 = 49 + 16 = 65$ instead of subtracting, yielding $h = 2\\sqrt{65}$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UC57EE', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'grid_in', E'In right triangle $DEF$, angle $D = 90°$, $DE = 7$, and $EF = 11$. What is the value of $\\sin(F)$? Express your answer as a fraction.', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7/11', ARRAY['7/11', '0.636', '.636'], E'In right triangle $DEF$ with the right angle at $D$, the side opposite angle $F$ is $DE = 7$ and the hypotenuse is $EF = 11$. By definition, $\\sin(F) = \\frac{\\text{opposite}}{\\text{hypotenuse}} = \\frac{7}{11}$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UEJ2MI', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'mcq', E'In a $30°$-$60°$-$90°$ triangle, the side opposite the $30°$ angle has length $9$. What is the length of the hypotenuse?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{9}{2}$"},{"key":"B","text":"$9\\sqrt{2}$"},{"key":"C","text":"$9\\sqrt{3}$"},{"key":"D","text":"$18$"}]$lyceon_json$::jsonb, 'D', NULL, E'In a $30°$-$60°$-$90°$ triangle, the side opposite the $30°$ angle is half the hypotenuse. Therefore hypotenuse $= 2 \\times 9 = 18$. The value $\\frac{9}{2}$ results from multiplying by $\\frac{1}{2}$ instead of $2$, reversing the relationship between the short leg and the hypotenuse. The value $9\\sqrt{2}$ results from incorrectly applying the $45°$-$45°$-$90°$ triangle ratio instead of the $30°$-$60°$-$90°$ ratio. The value $9\\sqrt{3}$ is the length of the side opposite the $60°$ angle, not the hypotenuse.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2US28R0', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A health researcher finds that adults who drink at least $3$ cups of green tea per day have lower rates of heart disease than those who drink no green tea. The study collected data from medical records of $4{,}700$ adults over a $10$-year period without intervening in their behavior. Which of the following is the most appropriate conclusion?', NULL, $lyceon_json$[{"key":"A","text":"Drinking green tea causes a reduction in heart disease."},{"key":"B","text":"There is an association between green tea consumption and lower rates of heart disease."},{"key":"C","text":"Adults who drink green tea are healthier in all respects than those who do not."},{"key":"D","text":"The study proves that green tea has no effect on heart disease."}]$lyceon_json$::jsonb, 'B', NULL, E'Because this is an observational study (no random assignment to treatment groups), the researcher can identify an association but cannot establish causation. Confounding variables (such as diet, exercise, or socioeconomic status) may explain the relationship. The claim that drinking green tea causes a reduction in heart disease incorrectly draws a causal conclusion from an observational study. The claim that green tea drinkers are healthier in all respects overgeneralizes the finding beyond what the data support -- the study measured only heart disease rates. The claim that the study proves green tea has no effect directly contradicts the observed data showing lower heart disease rates among green tea drinkers.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2UTCHBS', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 3, 'mcq', E'A chemist mixes two solutions. Solution P contains $13\\%$ acid and Solution Q contains $43\\%$ acid. The chemist needs exactly $600$ milliliters of a mixture that is $25\\%$ acid. How many milliliters of Solution Q are needed?', NULL, $lyceon_json$[{"key":"A","text":"$72$"},{"key":"B","text":"$240$"},{"key":"C","text":"$300$"},{"key":"D","text":"$360$"}]$lyceon_json$::jsonb, 'B', NULL, E'Let $p$ be the milliliters of Solution P and $q$ be the milliliters of Solution Q. The system is $p + q = 600$ and $0.13p + 0.43q = 0.25(600) = 150$. Substituting $p = 600 - q$ into the acid equation gives $0.13(600 - q) + 0.43q = 150$, which simplifies to $78 + 0.30q = 150$, so $0.30q = 72$ and $q = 240$. The value $72$ results from stopping at the intermediate step $0.30q = 72$ and reporting $72$ as the answer without completing the division. The value $300$ reflects the misconception that the mixture should contain equal volumes of each solution. The value $360$ results from correctly solving the system but reporting the amount of Solution P ($p = 600 - 240 = 360$) instead of Solution Q.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VL75UO', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A printer produces $37$ pages every $4$ minutes. At this constant rate, how many pages does the printer produce in $20$ minutes?', NULL, $lyceon_json$[{"key":"A","text":"$148$"},{"key":"B","text":"$185$"},{"key":"C","text":"$174$"},{"key":"D","text":"$160$"}]$lyceon_json$::jsonb, 'B', NULL, E'The rate is $\\frac{37}{4}$ pages per minute. In $20$ minutes: $\\frac{37}{4} \\times 20 = \\frac{740}{4} = 185$ pages. The value $148$ results from incorrectly computing $37 \\times 4$ instead of using the correct ratio. The value $174$ comes from an arithmetic error in the multiplication step. The value $160$ results from rounding the rate to $8$ pages per minute and multiplying by $20$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2VU2309', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'mcq', E'A surveyor standing at point $C$ measures the angle of elevation to the top of a building as $37°$. She then walks $50$ meters directly toward the building to point $D$ and measures the angle of elevation as $58°$. What is the height of the building, to the nearest meter?', NULL, $lyceon_json$[{"key":"A","text":"$38$"},{"key":"B","text":"$45$"},{"key":"C","text":"$71$"},{"key":"D","text":"$80$"}]$lyceon_json$::jsonb, 'C', NULL, E'Let $h$ be the building height and $x$ the horizontal distance from point $D$ to the base of the building. Then $\\tan(58°) = \\frac{h}{x}$ and $\\tan(37°) = \\frac{h}{x + 50}$. From these two equations, $x \\cdot \\tan(58°) = (x + 50) \\cdot \\tan(37°)$. Solving yields $x \\approx 44.5$, so $h = 44.5 \\times \\tan(58°) \\approx 71$ meters. The value $38$ results from computing $50 \\times \\tan(37°) \\approx 37.7$ and rounding, which incorrectly assumes the full distance to the building is $50$ meters. The value $45$ is the approximate horizontal distance $x$ from $D$ to the base, not the height. The value $80$ results from computing $50 \\times \\tan(58°) \\approx 80$, again assuming $50$ meters is the total horizontal distance but using the closer measurement angle.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2W6WZV2', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'mcq', E'A data set of $11$ positive integers has a mean of $17$, a median of $14$, and a mode of $11$. If the largest value in the data set is removed, the mean of the remaining $10$ values is $15$. What is the largest value in the original data set?', NULL, $lyceon_json$[{"key":"A","text":"$37$"},{"key":"B","text":"$39$"},{"key":"C","text":"$34$"},{"key":"D","text":"$27$"}]$lyceon_json$::jsonb, 'A', NULL, E'The sum of all $11$ values is $11 \\times 17 = 187$. The sum of the remaining $10$ values after removing the largest is $10 \\times 15 = 150$. Therefore the largest value is $187 - 150 = 37$. The value $39$ comes from an arithmetic error such as computing $11 \\times 17$ as $189$. The value $34$ results from incorrectly setting up the subtraction, such as using a wrong count. The value $27$ comes from using the median value in the computation, for example computing $187 - 10 \\times 16 = 27$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WJDPHG', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'A polling organization surveys a random sample of $900$ registered voters in a state and finds that $46\\%$ support Candidate X, with a margin of error of $\\pm 3.3$ percentage points at a $95\\%$ confidence level. A separate random sample of $900$ registered voters from the same state finds that $49\\%$ support Candidate Y, with the same margin of error. Which of the following conclusions is best supported by these results?', NULL, $lyceon_json$[{"key":"A","text":"Candidate Y will win the election because $49\\%$ is greater than $46\\%$."},{"key":"B","text":"The difference between the candidates' support levels is not statistically significant because the confidence intervals overlap."},{"key":"C","text":"Exactly $3\\%$ of voters in the state prefer Candidate Y over Candidate X."},{"key":"D","text":"The polls are unreliable because they were conducted on separate samples."}]$lyceon_json$::jsonb, 'B', NULL, E'Candidate X''s confidence interval is $42.7\\%$ to $49.3\\%$, and Candidate Y''s confidence interval is $45.7\\%$ to $52.3\\%$. Because these intervals overlap substantially, the observed $3$-percentage-point difference is within the range of sampling variability, meaning the difference is not statistically significant. The conclusion that Candidate Y will win because $49\\%$ exceeds $46\\%$ ignores the margin of error and treats sample estimates as exact population values. The claim that exactly $3\\%$ more voters prefer Candidate Y treats sample percentages as exact population parameters rather than estimates with uncertainty. The assertion that separate samples make the polls unreliable reflects a misunderstanding of statistical sampling -- independent random samples from the same population are a standard and valid methodology.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WLR3VN', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'grid_in', E'The equation $y = 1.7x + 23$ models the relationship between the number of hours spent studying, $x$, and the score on an exam, $y$, for a group of students. According to this model, what is the expected increase in exam score for a student who studies $9$ more hours than another student?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '15.3', ARRAY['15.3'], E'In the linear model $y = 1.7x + 23$, the slope $1.7$ represents the increase in $y$ for each unit increase in $x$. For $9$ additional hours, the expected increase is $1.7 \\times 9 = 15.3$. A common error is computing the predicted score at $x = 9$ (which would be $1.7(9) + 23 = 38.3$) rather than the increase alone. Another error is misreading the slope as the $y$-intercept.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WUNAWX', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'mcq', E'A researcher collects data on the age (in years) and resting heart rate (in beats per minute) of $40$ adults. The line of best fit is $h = -0.3a + 89$, where $h$ is the predicted resting heart rate and $a$ is the age. One participant is $53$ years old and has a resting heart rate of $68$ beats per minute. What is the residual for this participant, and what does it indicate?', NULL, $lyceon_json$[{"key":"A","text":"$5.1$; the model underpredicts this participant's heart rate"},{"key":"B","text":"$-5.1$; the model overpredicts this participant's heart rate"},{"key":"C","text":"$5.1$; the model overpredicts this participant's heart rate"},{"key":"D","text":"$-5.1$; the model underpredicts this participant's heart rate"}]$lyceon_json$::jsonb, 'B', NULL, E'The predicted heart rate for age $53$ is $h = -0.3(53) + 89 = -15.9 + 89 = 73.1$ beats per minute. The residual is actual minus predicted: $68 - 73.1 = -5.1$. A negative residual means the actual value is below the predicted value, so the model overpredicts this participant''s heart rate. The value $5.1$ with underprediction reverses the sign of the subtraction by computing predicted minus actual. The value $5.1$ with overprediction gets the correct magnitude but misinterprets the direction. The value $-5.1$ with underprediction gets the correct residual but misinterprets what a negative residual means.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XGRW3G', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'grid_in', E'If $9x - 23 = 40$, what is the value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'Adding $23$ to both sides gives $9x = 63$. Dividing both sides by $9$ gives $x = 7$.', NULL, NULL, 'draft', 1, 30, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XNUH2N', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'A researcher wants to determine whether a new fertilizer increases tomato plant yield. She randomly assigns $60$ tomato plants to two groups: one group receives the new fertilizer and the other receives no fertilizer. After $8$ weeks, she compares the average yield of each group. What type of study is this?', NULL, $lyceon_json$[{"key":"A","text":"An observational study"},{"key":"B","text":"A randomized experiment"},{"key":"C","text":"A survey"},{"key":"D","text":"A case study"}]$lyceon_json$::jsonb, 'B', NULL, E'Because the researcher randomly assigns plants to treatment and control groups, this is a randomized experiment. Random assignment allows the researcher to establish a cause-and-effect relationship. An observational study would involve observing existing groups without assigning a treatment, which is not what occurs here. A survey collects self-reported data from respondents, which does not apply to measuring plant yields under controlled conditions. A case study is an in-depth analysis of a single individual or small group, not a controlled comparison of two groups of $60$ plants.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YJXLOS', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'Two parallel lines are cut by a transversal. Two alternate interior angles have measures $(3x + 7)°$ and $(5x - 19)°$. What is the value of $x$?', NULL, $lyceon_json$[{"key":"A","text":"$6$"},{"key":"B","text":"$13$"},{"key":"C","text":"$24$"},{"key":"D","text":"$26$"}]$lyceon_json$::jsonb, 'B', NULL, E'Alternate interior angles formed by parallel lines and a transversal are equal, so $3x + 7 = 5x - 19$. Rearranging gives $7 + 19 = 5x - 3x$, which simplifies to $26 = 2x$, so $x = 13$. The value $6$ results from a sign error when combining constants, computing $19 - 7 = 12$ instead of $19 + 7 = 26$, yielding $2x = 12$. The value $24$ results from incorrectly treating the angles as co-interior (same-side interior) and setting their sum equal to $180°$, giving $8x - 12 = 180$. The value $26$ results from stopping at the intermediate step $2x = 26$ without dividing by $2$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZLNBXM', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'mcq', E'A shipping company charges $11$ dollars per small package and $19$ dollars per large package. The company must earn more than $253$ dollars from a shipment but can transport at most $17$ packages total. If $s$ is the number of small packages and $l$ is the number of large packages, what is the minimum number of large packages the company must include?', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$8$"},{"key":"C","text":"$9$"},{"key":"D","text":"$10$"}]$lyceon_json$::jsonb, 'C', NULL, E'The constraints are $11s + 19l > 253$ and $s + l \\leq 17$, with $s, l \\geq 0$. To minimize $l$, maximize $s$ by setting $s = 17 - l$. Substituting into the revenue constraint: $11(17 - l) + 19l > 253$, which simplifies to $187 + 8l > 253$, so $8l > 66$, giving $l > 8.25$. Since $l$ must be a whole number, the minimum is $l = 9$. Verification: with $9$ large and $8$ small packages, revenue is $11(8) + 19(9) = 88 + 171 = 259 > 253$, and $8 + 9 = 17 \\leq 17$. Choosing $7$ results from partial reasoning, such as computing $\\frac{253}{19} \\approx 13.3$ and subtracting from $17$ to get approximately $4$, then miscalculating further. Choosing $8$ comes from solving $l > 8.25$ but rounding down instead of up, or treating the strict inequality as non-strict. Choosing $10$ results from an extra rounding step or misreading the total-package constraint as $16$ instead of $17$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW20R7DR3', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which finding, if true, would most directly undermine the researchers'' conclusion?', E'Marine biologists studying coral reefs off the coast of Mozambique concluded that the observed 41 percent decline in staghorn coral coverage between 2014 and 2022 was primarily attributable to rising ocean temperatures associated with climate change. The researchers noted that three major thermal bleaching events occurred during this period and that staghorn corals, which are particularly sensitive to sustained temperatures above 29 degrees Celsius, suffered disproportionate mortality compared to massive coral species in the same reef system. They dismissed the potential contribution of increased sediment runoff from nearby coastal development, arguing that water clarity measurements showed no significant deterioration over the study period.', $lyceon_json$[{"key":"A","text":"Staghorn corals in laboratory settings have been shown to tolerate temperatures up to 31 degrees Celsius when provided with nutrient-enriched water, but the Mozambique reefs had consistently low nutrient levels during the study period."},{"key":"B","text":"Satellite imagery analysis reveals that water clarity at the study site declined substantially between 2016 and 2022, contradicting the researchers' in-situ measurements, which were taken at only three fixed monitoring stations."},{"key":"C","text":"A parallel study of coral reefs in the Seychelles documented a similar rate of staghorn coral decline during the same period and attributed it primarily to rising ocean temperatures."},{"key":"D","text":"Massive coral species at the Mozambique site experienced a 12 percent decline in coverage during the same period, a rate consistent with expected thermal stress impacts on heat-tolerant species."}]$lyceon_json$::jsonb, 'B', NULL, E'The researchers concluded that temperature was the primary cause and dismissed sediment runoff because water clarity showed no significant deterioration. The finding that satellite imagery contradicts their in-situ clarity measurements would directly undermine their dismissal of sediment runoff as a contributing factor, thereby challenging whether temperature alone explains the decline. The finding about laboratory coral tolerating higher temperatures with nutrient enrichment does not undermine the conclusion because the Mozambique reefs had low nutrient levels, meaning the lab conditions do not apply. The finding about similar declines in the Seychelles would support, not undermine, the temperature-based conclusion by showing the same pattern elsewhere. The finding about massive coral species declining at a rate consistent with thermal stress would also support the temperature explanation rather than challenge it.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
