INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW25HGB4G', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Paleontologist Yusuf al-Rashid, an expert on Cretaceous marine ______ recently proposed that mosasaur populations in the Western Interior Seaway may have been regulated by periodic episodes of oceanic anoxia rather than by competition for prey.', $lyceon_json$[{"key":"A","text":"reptiles recently"},{"key":"B","text":"reptiles; recently"},{"key":"C","text":"reptiles. Recently"},{"key":"D","text":"reptiles, recently"}]$lyceon_json$::jsonb, 'D', NULL, E'The sentence contains a nonrestrictive appositive, "an expert on Cretaceous marine reptiles," that renames and provides additional information about the subject "Paleontologist Yusuf al-Rashid." Because the appositive is introduced by a comma after "al-Rashid," it must be closed with a matching comma after "reptiles" before the sentence continues with the main verb "proposed." The option placing a comma after "reptiles" correctly closes the appositive. Omitting the comma after "reptiles" fails to close the appositive, producing a grammatically incomplete parenthetical structure. Using a semicolon after "reptiles" is incorrect because a semicolon cannot close an appositive phrase; semicolons join independent clauses. Placing a period after "reptiles" splits the sentence into a fragment ("Paleontologist Yusuf al-Rashid, an expert on Cretaceous marine reptiles." lacks a main verb) and another fragment ("Recently proposed that..." lacks a subject).', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW25TQDKH', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best describes the main idea of the text?', E'Literary scholar Tomoko Endo has challenged the prevailing view that Meiji-era Japanese novelists simply adopted Western narrative techniques wholesale. Analyzing seventeen novels published between 1887 and 1903, Endo demonstrates that authors such as Futabatei Shimei and Ozaki Koyo selectively incorporated elements of European realism—linear chronology, psychological interiority, third-person narration—while preserving structural features drawn from earlier Japanese literary traditions, including episodic pacing derived from serialized gesaku fiction and the integration of classical poetic allusion within prose passages. Endo argues that these hybrid forms constituted a deliberately negotiated synthesis rather than a passive absorption of foreign models.', $lyceon_json$[{"key":"A","text":"Meiji-era novelists created a deliberate blend of Western and traditional Japanese literary techniques rather than simply imitating European models."},{"key":"B","text":"Futabatei Shimei and Ozaki Koyo were the only Meiji-era novelists who successfully integrated European realism into Japanese fiction."},{"key":"C","text":"The structural features of gesaku fiction were incompatible with the techniques of European realism and required significant modification."},{"key":"D","text":"Tomoko Endo's research proves that Japanese literary traditions were more sophisticated than European literary traditions during the Meiji era."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage centers on Endo''s argument that Meiji-era novelists created a deliberate synthesis of Western and Japanese literary techniques, making the option about a deliberate blend the best description of the main idea. The option claiming Shimei and Koyo were the only successful integrators misreads the passage, which cites them as examples among seventeen novels, not as the sole practitioners. The option about gesaku features being incompatible with European realism goes beyond what the passage states; the passage describes integration, not incompatibility. The option about Japanese traditions being more sophisticated than European ones is an unsupported inference, as Endo''s argument concerns synthesis, not a qualitative ranking of literary traditions.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW274M6MY', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support the researchers'' hypothesis?', E'Agricultural scientists at the University of Saskatchewan hypothesize that crop yields of canola decline in fields where the same crop has been planted for four or more consecutive growing seasons because soil populations of the fungal pathogen Plasmodiophora brassicae increase substantially under continuous canola cultivation. The scientists predict that rotating canola with non-brassica crops such as barley or peas for at least two seasons would reduce pathogen levels and restore yields.', $lyceon_json$[{"key":"A","text":"Fields rotated with barley for two seasons showed a 34 percent decrease in Plasmodiophora brassicae levels and a corresponding increase in canola yield when canola was replanted."},{"key":"B","text":"Canola varieties bred for drought resistance produced higher yields than conventional varieties regardless of the number of consecutive seasons they were planted."},{"key":"C","text":"Soil samples from fields that had never been used for canola cultivation contained trace amounts of Plasmodiophora brassicae."},{"key":"D","text":"Farmers who applied synthetic fungicides to continuous canola fields reported mixed results in controlling Plasmodiophora brassicae infections."}]$lyceon_json$::jsonb, 'A', NULL, E'The hypothesis predicts that rotating canola with non-brassica crops would reduce pathogen levels and restore yields. The finding that barley rotation reduced Plasmodiophora brassicae levels and increased canola yield directly confirms both elements of this prediction. The finding about drought-resistant varieties addresses yield but not the pathogen mechanism central to the hypothesis, making it irrelevant as supporting evidence. The finding about trace pathogen amounts in fields never used for canola is tangential because the hypothesis concerns pathogen accumulation under continuous canola cultivation, not baseline pathogen presence. The finding about mixed fungicide results addresses a different intervention entirely and does not test the rotation hypothesis.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW27A6FOD', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'A student is writing an article for a campus science newsletter about recent developments in mycelium-based construction materials. The student wants to emphasize the environmental advantages of mycelium composites over traditional building materials. Which choice most effectively uses the relevant information from the notes to accomplish this goal?
