INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2BF84AJ', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which quotation from a literary critic, if accurate, would most directly support the student''s claim about the novel?', E'A student argues that in Chimamanda Ngozi Adichie''s novel Americanah, the protagonist Ifemelu''s blog posts function not merely as a plot device for expressing her opinions but as a structural element that mirrors the novel''s broader thematic concern with how public performance of identity shapes private self-understanding. The student claims that the blog posts create a recursive loop in which Ifemelu''s act of writing about race for an audience alters her own perception of her racial experiences.', $lyceon_json$[{"key":"A","text":"\"Ifemelu's blog entries serve as comic interludes that relieve the tension of the immigration narrative, providing readers with a lighter perspective on the challenges she faces in America.\""},{"key":"B","text":"\"The blog-within-the-novel operates as a performative mirror: Ifemelu constructs a public racial self through writing, and that constructed self in turn reshapes how she interprets her own lived experiences of race.\""},{"key":"C","text":"\"Adichie uses Ifemelu's blog to critique the superficiality of online discourse, suggesting that digital platforms encourage oversimplified discussions of complex social issues like race.\""},{"key":"D","text":"\"The blog posts in Americanah primarily serve an expository function, efficiently conveying background information about Nigerian and American racial dynamics that would otherwise require lengthy narrative passages.\""}]$lyceon_json$::jsonb, 'B', NULL, E'The student''s claim is that the blog posts create a recursive loop in which Ifemelu''s public writing about race reshapes her private self-understanding. The quotation describing the blog as a performative mirror where the constructed public self reshapes her interpretation of lived experience directly supports this recursive-loop claim. The quotation characterizing the blog entries as comic interludes addresses tone and reader experience, not the identity-formation loop the student describes. The quotation about critiquing online discourse superficiality addresses a different thematic reading of the blog and does not support the claim about self-perception being altered. The quotation describing the blog as primarily expository frames the posts as a narrative convenience rather than a recursive identity mechanism, which contradicts rather than supports the student''s argument.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2BTNUWB', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'When volcanologist Kenji Maeda analyzed gas emissions from Mount Ontake in September 2014, he detected unusually high levels of sulfur dioxide—a finding that, had it been reported sooner, ______ authorities to issue an evacuation warning before the deadly eruption that occurred just three days later.', $lyceon_json$[{"key":"A","text":"will prompt"},{"key":"B","text":"would have prompted"},{"key":"C","text":"had prompted"},{"key":"D","text":"would prompt"}]$lyceon_json$::jsonb, 'B', NULL, E'The sentence establishes a past counterfactual conditional with the clause "had it been reported sooner," which uses the past perfect subjunctive to describe a hypothetical condition that did not occur. The result clause of a past counterfactual requires "would have" plus the past participle. The form "would have prompted" correctly completes this construction. The future tense form "will prompt" is incorrect because the events described occurred in 2014; a future tense is incompatible with a past counterfactual. The past perfect form "had prompted" alone does not complete the conditional construction; it merely restates the past perfect without indicating the hypothetical result. The form "would prompt" expresses a present or future hypothetical, not a past counterfactual; the past counterfactual specifically requires "would have" plus the past participle to indicate an unrealized outcome.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2C4GB1K', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'A student is writing a proposal for a linguistics seminar arguing that the decline of indigenous sign languages deserves more scholarly attention. The student wants to acknowledge a counterargument while ultimately reinforcing the urgency of studying these languages. Which choice most effectively uses the relevant information from the notes to accomplish this goal?
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2CJZUVW', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The international review board recommended that the pharmaceutical company ______ its Phase III clinical trial data for independent verification before seeking regulatory approval, citing concerns about the statistical methods used to evaluate the drug''s efficacy in patients with treatment-resistant depression.', $lyceon_json$[{"key":"A","text":"releases"},{"key":"B","text":"released"},{"key":"C","text":"would release"},{"key":"D","text":"release"}]$lyceon_json$::jsonb, 'D', NULL, E'The verb "recommended" triggers the subjunctive mood in the "that" clause that follows. In Standard English, verbs of recommendation, demand, and suggestion (such as "recommended," "insisted," "required") require the base (bare infinitive) form of the verb in the subordinate "that" clause, regardless of the subject''s number. The base form "release" correctly fulfills this requirement. The third-person singular indicative form "releases" is incorrect because the subjunctive, not the indicative, is required after "recommended that." The past tense form "released" is also incorrect; the subjunctive does not inflect for tense in this construction. The conditional form "would release" is non-standard in formal mandative subjunctive clauses and is not accepted as correct in Standard English conventions tested on the SAT.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2D0FUHM', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'Entomologist Clara Vásquez studied firefly populations in eleven rural counties in Tennessee between 2018 and 2023. She found that counties where residents had adopted ordinances restricting outdoor artificial lighting after 10 p.m. showed firefly population densities 2.7 times greater than counties without such ordinances. Vásquez noted that artificial light disrupts the bioluminescent mating signals that fireflies use to locate partners. Based on these findings, Vásquez suggested that ________', $lyceon_json$[{"key":"A","text":"firefly populations could benefit from policies that limit nighttime artificial lighting in rural areas."},{"key":"B","text":"fireflies in Tennessee are genetically distinct from firefly populations in other southeastern states."},{"key":"C","text":"outdoor lighting ordinances were originally enacted for the purpose of protecting firefly habitats."},{"key":"D","text":"firefly population densities are unaffected by factors other than artificial lighting levels."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes a correlation between lighting restrictions and higher firefly populations and explains the mechanism by which light disrupts firefly mating. The completion suggesting fireflies could benefit from policies limiting nighttime lighting follows logically from these findings. The completion about genetic distinctness has no basis in the passage, which discusses lighting and population density, not genetics. The completion about ordinances being enacted to protect firefly habitats overreaches because the passage describes a correlation between ordinances and firefly populations but does not address why the ordinances were originally adopted. The completion claiming artificial lighting is the only factor affecting firefly populations overstates the findings, which show lighting matters but do not rule out other contributing factors.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2DJVNWF', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the underlined sentence in the overall structure of the text?', E'The fruit fly Drosophila melanogaster has been a staple of genetics research for over a century. Its genome was among the first to be fully sequenced, and its short reproductive cycle allows scientists to observe multiple generations within weeks. _These practical advantages, however, are not the only reason the species remains central to modern biology._ Recent studies have revealed that Drosophila shares roughly 75 percent of known human disease genes, making it an unexpectedly powerful model for studying conditions ranging from Parkinson''s disease to diabetes.', $lyceon_json$[{"key":"A","text":"It introduces a contrast between the traditional reasons for using Drosophila and an additional reason discussed afterward."},{"key":"B","text":"It summarizes the main argument of the passage by listing the key advantages of Drosophila research."},{"key":"C","text":"It provides a specific example that supports the claim made in the preceding sentence."},{"key":"D","text":"It challenges a widely held assumption about the limitations of Drosophila as a research organism."}]$lyceon_json$::jsonb, 'A', NULL, E'The underlined sentence uses the phrase ''however, are not the only reason,'' which signals a pivot from the practical advantages already discussed (short reproductive cycle, early genome sequencing) to an additional reason (shared disease genes) introduced in the following sentence. The option stating the sentence introduces a contrast between traditional reasons and an additional reason accurately captures this transitional function. The option claiming it summarizes the main argument is incorrect because the sentence does not list or recap; it pivots to new information. The option suggesting it provides a specific example mischaracterizes the sentence, which makes no specific claim but instead signals that more information follows. The option about challenging a widely held assumption overstates the sentence''s function; it does not dispute limitations but merely adds a further reason for Drosophila''s importance.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2F7Z1AM', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'Archaeologist Henning Bjørnstad excavated a Viking-age trading post in Vestfold, Norway, and recovered 213 glass bead fragments. Chemical analysis revealed that 74 percent of the beads contained natron, a flux mineral sourced exclusively from deposits in Wadi El Natrun, Egypt, during the period in question. However, the morphological characteristics of the beads—including their shapes, color layering techniques, and pontil marks—matched production methods documented at glassworking sites in Ribe, Denmark, rather than any known Egyptian or Levantine workshop. Bjørnstad therefore concluded that ________', $lyceon_json$[{"key":"A","text":"the beads were manufactured in Scandinavia using raw glass materials that had been imported from Egypt through long-distance trade networks."},{"key":"B","text":"Viking-age glassworkers in Ribe, Denmark, independently developed techniques for producing natron without access to Egyptian mineral deposits."},{"key":"C","text":"the beads were produced in Egyptian workshops but were later modified by Scandinavian artisans who altered their shapes and surface treatments."},{"key":"D","text":"chemical analysis is an unreliable method for determining the geographic origin of raw materials used in Viking-age glass production."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage establishes two key facts: the raw material (natron) came from Egypt, and the production techniques match a Danish workshop. The logical conclusion is that the beads were made in Scandinavia using imported Egyptian raw materials, reconciling both pieces of evidence. The option about independent natron production contradicts the passage''s statement that natron was sourced exclusively from Egyptian deposits during this period. The option about Egyptian production with later Scandinavian modification fails to account for the pontil marks and production methods matching Danish rather than Egyptian workshops, which indicate primary manufacture in Scandinavia. The option dismissing chemical analysis as unreliable contradicts the passage, in which the researcher relies on chemical analysis as valid evidence to reach a conclusion.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2G7HJK6', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The collection of seventeenth-century maritime charts housed in the Biblioteca Nazionale di Napoli ______ a detailed record of European navigational knowledge during the Age of Exploration.', $lyceon_json$[{"key":"A","text":"provide"},{"key":"B","text":"provides"},{"key":"C","text":"are providing"},{"key":"D","text":"have provided"}]$lyceon_json$::jsonb, 'B', NULL, E'The subject of the sentence is "collection," which is singular. The prepositional phrases "of seventeenth-century maritime charts" and "housed in the Biblioteca Nazionale di Napoli" modify the subject but do not change its number. The singular verb form "provides" correctly agrees with the singular subject "collection." The plural form "provide" incorrectly agrees with "charts," which is the object of the preposition, not the subject. The plural progressive form "are providing" also fails subject-verb agreement because "are" is plural. The plural perfect form "have provided" likewise disagrees with the singular subject.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2GQDUTQ', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the second sentence in the text?', E'The philosopher Kwame Gyekye has argued that communalism in Akan thought does not diminish the moral agency of individuals but instead locates that agency within a web of reciprocal obligations. Some scholars have interpreted this claim as a concession to Western liberal individualism, suggesting that Gyekye softens the communal emphasis found in earlier Akan philosophical writings to make it palatable to an international academic audience. Gyekye, however, grounds his position in proverbs and juridical practices documented in precolonial Akan societies, evidence that predates any contact with European philosophical traditions.', $lyceon_json$[{"key":"A","text":"It presents a criticism of Gyekye's argument that the remainder of the text goes on to counter."},{"key":"B","text":"It offers an example that supports the claim introduced in the first sentence."},{"key":"C","text":"It restates the argument from the first sentence using more accessible language for a general audience."},{"key":"D","text":"It introduces Gyekye's primary evidence for the philosophical position described in the first sentence."}]$lyceon_json$::jsonb, 'A', NULL, E'The second sentence describes scholars who interpret Gyekye''s claim as a concession to Western liberal individualism, framing it as an accommodation for an international audience. The third sentence then counters this criticism by pointing to precolonial Akan evidence that predates European contact. The option identifying the second sentence as a criticism that the rest of the text counters accurately captures this structure. The option claiming it offers a supporting example is incorrect because the second sentence challenges rather than supports Gyekye''s position. The option suggesting it restates the first sentence in simpler language is wrong because the second sentence introduces an opposing scholarly interpretation, not a paraphrase. The option claiming it introduces Gyekye''s primary evidence misattributes the evidence to the second sentence; the precolonial proverbs and juridical practices appear in the third sentence, not the second.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2I2G2WO', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The fossilized trackways discovered in a sandstone formation near the village of Pemba date to approximately 113 million years ______ they constitute the first definitive evidence of sauropod dinosaurs in what is now the central highlands of Mozambique.', $lyceon_json$[{"key":"A","text":"ago, they"},{"key":"B","text":"ago they"},{"key":"C","text":"ago; they"},{"key":"D","text":"ago; and they"}]$lyceon_json$::jsonb, 'C', NULL, E'The sentence contains two independent clauses: "The fossilized trackways...date to approximately 113 million years ago" and "they constitute the first definitive evidence..." These two independent clauses require appropriate punctuation between them. The option using a semicolon correctly joins the two independent clauses without a coordinating conjunction. Placing only a comma between the clauses creates a comma splice, which is a boundary error in Standard English. Omitting all punctuation produces a fused sentence (run-on), which is also incorrect. Using a semicolon followed by the coordinating conjunction "and" is non-standard; a semicolon replaces the conjunction, so combining both is redundant and grammatically incorrect.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 80, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2ICS37X', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'In a 2023 study published in the journal Fungal Ecology, mycologist Priya Chattopadhyay and her colleagues examined networks of mycorrhizal fungi in old-growth hemlock forests of coastal British Columbia. The researchers found that individual fungal networks connected as many as forty-seven distinct trees, facilitating the transfer of carbon, nitrogen, and phosphorus between them. Chattopadhyay''s team concluded that these fungal networks function as a communal resource-sharing system, enabling younger or shaded trees to receive nutrients they could not obtain through photosynthesis alone.', $lyceon_json$[{"key":"A","text":"Mycorrhizal fungi in hemlock forests connect dozens of trees and serve as a system for sharing nutrients among them."},{"key":"B","text":"Priya Chattopadhyay's research methods have transformed the field of mycology by introducing new techniques for studying fungal networks."},{"key":"C","text":"Old-growth hemlock forests in British Columbia are ecologically unique because they contain a greater diversity of fungal species than other forests."},{"key":"D","text":"Younger trees in hemlock forests rely exclusively on mycorrhizal fungi rather than photosynthesis to obtain the nutrients they need."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes research showing that mycorrhizal fungi connect many trees in hemlock forests and facilitate nutrient sharing, making the option about fungal networks serving as a nutrient-sharing system the best statement of the main idea. The option about transforming the field of mycology misreads the passage, which describes findings rather than methodological innovations. The option about greater fungal diversity is an unsupported inference, since the passage does not compare fungal diversity across forest types. The option stating younger trees rely exclusively on fungi distorts the passage, which says fungi supplement what trees cannot obtain through photosynthesis alone, not that trees abandon photosynthesis entirely.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2KPVWHR', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best states the main idea of the text?', E'Neuroscientist Raúl Mendoza-Ferrer and his team investigated a paradox in auditory processing: experienced orchestral musicians consistently outperform nonmusicians on tasks requiring the detection of subtle pitch deviations, yet they show no measurable advantage on tasks requiring the detection of subtle timing deviations, even though precise timing is equally essential to musical performance. Using magnetoencephalography to map cortical responses in 83 participants, Mendoza-Ferrer found that musicians exhibited enhanced neural activity in the right auditory cortex during pitch-deviation tasks but showed activation patterns indistinguishable from those of nonmusicians during timing-deviation tasks. He proposed that pitch discrimination, unlike timing discrimination, depends on domain-specific neural refinements that accumulate through years of targeted auditory training, whereas timing discrimination relies on broadly distributed neural circuits that are not substantially reshaped by musical expertise.', $lyceon_json$[{"key":"A","text":"Musicians' superior pitch detection, unlike their timing detection, appears to result from specialized neural changes produced by sustained musical training."},{"key":"B","text":"Orchestral musicians are less skilled at detecting timing deviations than previously believed because they focus primarily on pitch during performances."},{"key":"C","text":"Magnetoencephalography has revealed that the right auditory cortex is the sole brain region responsible for processing both pitch and timing in music."},{"key":"D","text":"Musical training enhances all forms of auditory processing, though pitch-related improvements are more easily measured than timing-related improvements."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes a paradox in which musicians excel at pitch detection but not timing detection, and the researcher proposes that pitch discrimination depends on domain-specific neural refinements from training while timing discrimination does not. The option about specialized neural changes for pitch detection captures this central idea. The option attributing musicians'' timing results to a performance focus on pitch is an unsupported inference, as the passage offers a neural explanation rather than an attentional one. The option about the right auditory cortex being the sole region for both pitch and timing misreads the findings: the passage mentions enhanced right auditory cortex activity only for pitch tasks and describes timing as relying on broadly distributed circuits. The option claiming musical training enhances all auditory processing contradicts the passage''s central finding that timing detection is not enhanced, and its framing of the difference as merely a measurement issue misrepresents the researcher''s neural explanation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2LAVJ9D', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'Geochemist Marta Olejnik''s 2021 analysis of sediment cores from Lake Ohrid, straddling the border of Albania and North Macedonia, challenged the prevailing model of Mediterranean climate shifts during the late Pleistocene. Earlier researchers had attributed a period of pronounced aridity around 130,000 years ago to reduced Atlantic moisture transport. Olejnik''s isotopic data, however, indicated that monsoon-driven moisture from the south actually intensified during this interval, suggesting that the aridity recorded in western Mediterranean sites did not extend uniformly eastward. She proposed a revised framework in which the eastern and western basins responded to distinct atmospheric circulation patterns rather than a single continental-scale driver.', $lyceon_json$[{"key":"A","text":"It presents a researcher's finding, describes the evidence that contradicts a prior model, and outlines the alternative framework the researcher proposes."},{"key":"B","text":"It compares two lakes to demonstrate that climate patterns in the Mediterranean varied by geographic location during the Pleistocene."},{"key":"C","text":"It traces the chronological development of Mediterranean climate research from early studies to the most recent consensus."},{"key":"D","text":"It describes an experimental method in detail and then evaluates whether the results are statistically significant."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage first introduces Olejnik''s challenge to the prevailing model, then presents isotopic evidence that contradicts the earlier aridity explanation, and finally outlines her revised framework of distinct atmospheric circulation patterns. The option describing this three-part structure — finding, contradicting evidence, alternative framework — accurately captures the text''s organization. The option about comparing two lakes is incorrect because only Lake Ohrid is analyzed; western Mediterranean sites are referenced but no second lake is compared in detail. The option about tracing chronological development misrepresents the passage, which does not survey the history of the field but focuses on one researcher''s challenge to a single prior model. The option about describing an experimental method and evaluating statistical significance is incorrect because the passage mentions isotopic data without detailing laboratory methods or discussing statistical analysis.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"detail_misread"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2M8Q20C', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'A student is writing a report about the Japanese art of kintsugi for an art history class. The student wants to define kintsugi for readers who may be unfamiliar with it. Which choice most effectively uses the relevant information from the notes to accomplish this goal?
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2MKBGUQ', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Marine biologist Kendra Okafor has spent over a decade studying the migratory patterns of loggerhead sea turtles in the western Atlantic. Her research has shown that ocean temperature fluctuations significantly influence the timing of annual migrations. _______ Okafor recently published findings indicating that warmer winter currents have caused turtles to delay their southward departures by an average of seventeen days compared to records from the 1990s.', $lyceon_json$[{"key":"A","text":"For instance,"},{"key":"B","text":"In contrast,"},{"key":"C","text":"Nevertheless,"},{"key":"D","text":"Meanwhile,"}]$lyceon_json$::jsonb, 'A', NULL, E'The second sentence states that ocean temperature fluctuations influence migration timing, and the sentence after the blank provides a specific example of this influence — warmer currents causing delayed departures. The transition "For instance," correctly signals that an example follows. "In contrast," incorrectly suggests the final sentence contradicts what precedes it, when in fact it supports it. "Nevertheless," implies an unexpected outcome despite the preceding information, but the finding is consistent with, not contrary to, the claim about temperature effects. "Meanwhile," suggests simultaneous but unrelated events, whereas the final sentence is directly connected as an illustration of the preceding claim.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2PFNDZ5', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The documentary chronicles how the architect not only defied municipal zoning regulations by constructing a seventeen-story tower on land designated for single-family residences but also ______ permits for the project by submitting falsified environmental impact assessments to three separate oversight agencies.', $lyceon_json$[{"key":"A","text":"had been obtaining"},{"key":"B","text":"obtains"},{"key":"C","text":"obtaining"},{"key":"D","text":"obtained"}]$lyceon_json$::jsonb, 'D', NULL, E'The sentence uses the correlative conjunction pair "not only...but also," which requires parallel grammatical structure on both sides. The first element is the past tense verb "defied" ("not only defied municipal zoning regulations"), so the second element must also be a past tense verb to maintain parallelism: "but also obtained permits." The past tense form "obtained" correctly parallels "defied." The past perfect progressive form "had been obtaining" breaks the parallel structure by introducing a different tense and aspect. The present tense form "obtains" also breaks parallelism because the first verb is past tense; additionally, the events described are historical, making present tense contextually wrong. The gerund form "obtaining" is not a finite verb and cannot parallel the finite past tense verb "defied"; it would leave the "but also" clause without a conjugated verb.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2PO3N2B', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'In her 2019 monograph on Byzantine mosaics, art historian Eleni Vassilaki argues that scholars have too readily assumed the Ravenna mosaics were designed to ______ imperial power. She contends that the tessellation patterns encode theological arguments about the nature of light itself, arguments that would have been legible to clergy but largely opaque to visiting dignitaries.', $lyceon_json$[{"key":"A","text":"consolidate"},{"key":"B","text":"glorify"},{"key":"C","text":"undermine"},{"key":"D","text":"delegate"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage describes a scholarly assumption that Vassilaki challenges: that the mosaics were designed to celebrate or exalt imperial power. She counters this by arguing the mosaics actually encode theological arguments. "Glorify" means to praise, honor, or celebrate, which fits the conventional scholarly view that mosaics served as visual celebrations of imperial authority. "Consolidate" means to strengthen or make more secure, which implies a political strategy of unifying power rather than a visual display meant to celebrate it; mosaics are artistic displays, not political mechanisms for consolidating authority. "Undermine" means to weaken or subvert, which would mean scholars believed the mosaics worked against imperial power, contradicting the passage''s framing of a positive conventional interpretation that Vassilaki is revising. "Delegate" means to assign responsibility to another, which describes administrative action and has no connection to how mosaics relate to imperial power.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2QNNJZO', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'The architect Lina Bo Bardi resisted the prevailing European modernist aesthetic when she relocated to Brazil in 1946. Rather than importing rigid design templates, she ______ local building traditions, incorporating indigenous materials and folk art motifs into her concrete structures in ways that unsettled her more doctrinaire contemporaries.', $lyceon_json$[{"key":"A","text":"embraced"},{"key":"B","text":"cataloged"},{"key":"C","text":"satirized"},{"key":"D","text":"fabricated"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage contrasts Bo Bardi''s approach with importing rigid templates, then describes her incorporating indigenous materials and folk art into her structures. This indicates she warmly adopted local traditions. "Embraced" means enthusiastically accepted and adopted, which matches the description of actively incorporating local elements into her work. "Cataloged" means systematically recorded or listed, which implies documentation rather than the active incorporation described in the passage. "Satirized" means mocked or ridiculed through imitation, which contradicts the respectful integration of local traditions described. "Fabricated" means invented or made up, which would imply the traditions were false, contradicting the passage''s depiction of genuine local building practices.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2RPWVO1', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'While investigating the microbial communities thriving in hydrothermal vents along the Mid-Atlantic ______ several species of archaea capable of surviving in temperatures exceeding 121 degrees Celsius.', $lyceon_json$[{"key":"A","text":"Ridge, biochemist Fátima Guerrero-Solís identified"},{"key":"B","text":"Ridge. Biochemist Fátima Guerrero-Solís identified"},{"key":"C","text":"Ridge; biochemist Fátima Guerrero-Solís identified"},{"key":"D","text":"Ridge biochemist Fátima Guerrero-Solís identified"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence begins with the subordinate clause "While investigating the microbial communities thriving in hydrothermal vents along the Mid-Atlantic Ridge," which is a dependent introductory element and requires a comma before the main clause. The option placing a comma after "Ridge" correctly sets off this introductory dependent clause from the independent clause that follows. Using a period after "Ridge" is incorrect because the "While" clause is dependent and cannot stand alone as a sentence, creating a fragment. A semicolon after "Ridge" fails for the same reason: semicolons join two independent clauses, but the "While" clause is not independent. Omitting all punctuation after "Ridge" produces a run-on structure that merges the introductory clause into the main clause without the required separation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2S6TXJ8', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Urban planner Fatima El-Atassi has documented how the construction of elevated highways in several mid-twentieth-century American cities disproportionately displaced communities of color, severing established social networks and reducing property values in adjacent neighborhoods. Many cities have since acknowledged these harms; Portland, Oregon, for example, removed a segment of Harbor Drive in 1974, and Rochester, New York, began dismantling its Inner Loop in 2017. _______ El-Atassi''s longitudinal analysis of fourteen removal projects reveals that the economic benefits of highway removal — increased property values, new commercial activity — have accrued primarily to newer, wealthier residents rather than to the descendants of those originally displaced.', $lyceon_json$[{"key":"A","text":"Furthermore,"},{"key":"B","text":"As a result,"},{"key":"C","text":"However,"},{"key":"D","text":"Similarly,"}]$lyceon_json$::jsonb, 'C', NULL, E'The sentence before the blank describes cities undertaking highway removal as an acknowledgment of past harms, implying these projects aim to rectify historical injustices. The sentence after the blank reveals that the economic benefits of removal have gone to newer, wealthier residents rather than to the originally displaced communities — an outcome that undercuts the restorative intent. "However," correctly signals this contrast between the apparent corrective purpose and the actual inequitable outcome. "Furthermore," would indicate an additional point in the same direction, but the final sentence introduces a complication that works against the positive narrative of acknowledging and addressing harms. "As a result," implies the inequitable distribution of benefits is a direct consequence of cities acknowledging past wrongs, which misrepresents the logical relationship — the acknowledgment was meant to help displaced communities, not cause further inequity. "Similarly," suggests the final sentence parallels the preceding one, but it actually introduces a contradicting finding about who benefits from the removal projects.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2TSPSVC', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Cognitive scientist Haruto Nishikawa has argued that bilingual speakers do not simply switch between two separate linguistic systems but instead maintain a single integrated network in which both languages remain simultaneously active. This model predicts that elements from one language should subtly influence processing in the other, even in monolingual contexts. _______ when Nishikawa''s team tested fluent Korean-English bilinguals on an English lexical decision task, participants responded more slowly to English words that had phonologically similar counterparts in Korean, suggesting persistent cross-linguistic activation rather than selective suppression of the non-target language.', $lyceon_json$[{"key":"A","text":"In addition,"},{"key":"B","text":"By contrast,"},{"key":"C","text":"Consistent with this prediction,"},{"key":"D","text":"That is,"}]$lyceon_json$::jsonb, 'C', NULL, E'The second sentence articulates a specific prediction derived from Nishikawa''s model — that one language should influence processing in the other. The final sentence then describes experimental results that confirm exactly this prediction: cross-linguistic phonological interference during a monolingual task. "Consistent with this prediction," precisely captures the relationship between a theoretical expectation and empirical evidence that supports it. "In addition," merely signals additional information without conveying that the experimental findings directly validate the stated prediction; it obscures the confirmatory relationship. "By contrast," implies the experimental results contradict or diverge from the preceding claim, but the results actually align with the prediction. "That is," signals a restatement or clarification of the same idea in different terms, but the final sentence introduces new empirical data rather than rephrasing the prediction.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2W4WW4Y', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Economist Seonaid Mackinnon analyzed wage data from 1,247 software firms across fourteen European countries between 2015 and 2023. She found that firms adopting transparent salary disclosure policies—where all employees can view the compensation of every colleague—initially experienced a compression of wages: salaries for top performers declined by an average of 6 percent while salaries for lower-performing employees rose by an average of 3 percent. However, Mackinnon also observed that within three years of adopting transparency, these same firms saw their top performers'' salaries rebound to levels 4 percent above pre-transparency baselines, even as lower performers'' salaries stabilized at the modestly elevated level. Mackinnon proposed that the long-term pattern can be explained by the fact that ________', $lyceon_json$[{"key":"A","text":"transparency initially pressures firms to reduce conspicuous pay disparities, but over time it provides top performers with concrete benchmarking data that strengthens their negotiating position for raises."},{"key":"B","text":"transparent salary policies cause firms to abandon performance-based compensation structures entirely in favor of uniform pay scales determined solely by seniority."},{"key":"C","text":"the initial compression of wages under transparency policies reflects measurement error in the first year of data collection rather than a genuine change in compensation practices."},{"key":"D","text":"top performers at firms with transparent salary policies consistently leave for competitors within three years, forcing their original employers to raise wages to attract replacements of comparable skill."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes a two-phase pattern: initial wage compression followed by a rebound in top performers'' salaries alongside stabilized gains for lower performers. The completion about transparency first pressuring firms to reduce disparities and then giving top performers benchmarking leverage logically accounts for both phases. The option about abandoning performance-based pay entirely contradicts the passage''s evidence that top performers'' salaries eventually exceeded pre-transparency levels, which indicates performance-based differentiation persists. The option attributing the initial compression to measurement error contradicts the passage, which presents the compression as a genuine finding observed across over a thousand firms and multiple countries. The option about top performers leaving for competitors introduces an external mechanism (employee departures) that the passage does not reference and fails to explain why the same firms'' top performers'' salaries rebounded rather than why replacement salaries would be set higher.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WRUTXA', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'Which choice completes the text with the most logical and precise word?', E'Marine biologists have long recognized that coral reefs serve as crucial nurseries for juvenile fish. Without these protective structures, young fish would be ______ to predators during their most vulnerable developmental stages.', $lyceon_json$[{"key":"A","text":"exposed"},{"key":"B","text":"indifferent"},{"key":"C","text":"committed"},{"key":"D","text":"adjacent"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes young fish lacking the protective structures of coral reefs during vulnerable stages, so the blank requires a word meaning left open or unprotected against predators. "Exposed" means left without shelter or defense, which fits the context of being vulnerable without protection. "Indifferent" means having no interest or concern, which describes an emotional state irrelevant to the predator-prey relationship described. "Committed" means dedicated or pledged to something, which has no logical connection to the idea of lacking protection. "Adjacent" means next to or near, which describes spatial proximity but not the concept of vulnerability or lack of defense.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2XW98N2', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The microplastic filtration membrane that environmental engineer Suki Watanabe-Flores designed for use in municipal wastewater treatment ______ which can capture polymer fragments as small as 0.7 micrometers in diameter, has attracted interest from seventeen water utility companies across the Pacific Northwest.', $lyceon_json$[{"key":"A","text":"facilities"},{"key":"B","text":"facilities;"},{"key":"C","text":"facilities."},{"key":"D","text":"facilities,"}]$lyceon_json$::jsonb, 'D', NULL, E'The sentence layers two relative clauses onto the noun "membrane": a restrictive clause introduced by "that" ("that environmental engineer Suki Watanabe-Flores designed for use in municipal wastewater treatment facilities") and a nonrestrictive clause introduced by "which" ("which can capture polymer fragments as small as 0.7 micrometers in diameter"). The nonrestrictive "which" clause must be set off by commas, so a comma is required after "facilities" to open this clause; the closing comma appears later, after "diameter," before the main verb "has attracted." The option placing a comma after "facilities" correctly opens the nonrestrictive clause. Omitting all punctuation after "facilities" incorrectly attaches "which" without the comma required for nonrestrictive modification, violating Standard English convention. A semicolon after "facilities" is incorrect because a semicolon cannot introduce a nonrestrictive relative clause embedded within a noun phrase. A period after "facilities" creates a fragment ("Which can capture...has attracted...") beginning with a relative pronoun that lacks an antecedent in its own sentence.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 100, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
