INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2YY33H2', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'Archaeologists working at the Tlaxcallan site in central Mexico have challenged the long-held assumption that pre-Columbian states in Mesoamerica were invariably organized as hierarchical kingdoms. Excavations revealed that Tlaxcallan''s civic architecture lacked the palatial compounds typical of monarchical centers, suggesting a more distributed form of governance. _______ the city''s residential zones show remarkably uniform access to imported obsidian tools, a pattern inconsistent with the concentrated elite wealth observed at contemporary Aztec sites.', $lyceon_json$[{"key":"A","text":"Specifically,"},{"key":"B","text":"Moreover,"},{"key":"C","text":"Nonetheless,"},{"key":"D","text":"Accordingly,"}]$lyceon_json$::jsonb, 'B', NULL, E'The sentence before the blank notes the absence of palatial compounds as evidence of distributed governance, and the sentence after the blank introduces an additional, distinct piece of evidence — uniform access to obsidian tools. "Moreover," correctly signals the addition of a further supporting point. "Specifically," would be appropriate if the final sentence elaborated on the same detail about civic architecture, but it instead introduces a separate category of evidence (residential material distribution). "Nonetheless," incorrectly implies the final sentence presents an outcome that is surprising given the preceding information, when both sentences support the same conclusion. "Accordingly," suggests the final sentence describes a consequence or result of the architectural findings, but uniform obsidian access is an independent observation, not a consequence of lacking palaces.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
